import math
S=('A','B'); p0={'A':.5,'B':.5}; q={'A':.75,'B':.25}
P={'A':{'00':.4,'01':.1,'10':.1,'11':.4},'B':{'00':.1,'01':.4,'10':.4,'11':.1}}; h='11'
def norm(d):
 t=sum(d.values()); return {k:v/t for k,v in d.items()}
p1={s:sum(v for x,v in P[s].items() if x.startswith(h[:1])) for s in S}; m1=sum(p0[s]*p1[s] for s in S); f1={s:math.log(p1[s]/m1) for s in S}
p2={s:P[s][h] for s in S}; m2=sum(p0[s]*p2[s] for s in S); f2={s:math.log(p2[s]/m2) for s in S}; post=norm({s:p0[s]*math.exp(f2[s]) for s in S}); inc={s:f2[s]-f1[s] for s in S}
point={(s,t,y):sum(v for x,v in P[s].items() if x[t]==y) for s in S for t in (0,1) for y in ('0','1')}; naive=norm({s:p0[s]*point[(s,0,h[0])]*point[(s,1,h[1])] for s in S})
mq=sum(q[s]*p2[s] for s in S); fw={s:math.log(q[s]*p2[s]/(p0[s]*mq)) for s in S}; wrong=norm({s:p0[s]*math.exp(fw[s]) for s in S})
moment=0
for x in P['A']:
 mx=sum(q[s]*P[s][x] for s in S)
 for s in S: moment+=p0[s]*mx*math.exp(math.log(q[s]*P[s][x]/(p0[s]*mx)))
print('f1',f1,'f2',f2,'post',post,'inc',inc,'delta',inc['A']-inc['B'])
print('naive',naive,'naive_margin',math.log(naive['A']/naive['B']),'full_margin',math.log(post['A']/post['B']))
print('equivariance_error',max(abs(a-b) for a,b in zip([f2['B'],f2['A']],reversed([f2['A'],f2['B']]))))
print('negative_only',wrong,'odds',wrong['A']/wrong['B'],'correct_odds',post['A']/post['B'],'moment',moment)
print('zero_support',.2/0 if False else float('inf'),'positive_pairs',0)
